def _smallq_decode_xqa_allowed(self, query: torch.Tensor, key_cache: torch.Tensor, value_cache: torch.Tensor, seq_lens: torch.Tensor, attn_metadata: TritonAttentionMetadata, *, window_size: tuple[int, int], max_seq_len_hint: int | None, workspace_seq_capacity_hint: int | None, partition_size_hint: int | None) -> bool:
    if not self.use_smallq_decode_xqa or self.flash_attn_decode_paged_xqa is None or partition_size_hint is not None or (window_size != (-1, -1)) or (query.shape[0] != seq_lens.shape[0]) or (query.shape[2] != 256) or (key_cache.shape[2] <= 0) or (query.shape[1] % key_cache.shape[2] != 0):
        return False
    q_per_kv = query.shape[1] // key_cache.shape[2]
    if q_per_kv not in (6, 8):
        return False
    codec = self._xqa_kv_codec(key_cache, value_cache, attn_metadata)
    if codec is None:
        return False
    fp8_e5m2_kv = codec is FP8_E5M2
    if codec is FP8_E4M3 and (q_per_kv != 6 or (query.shape[0] > 1 and (not _routing._e4m3_batch_xqa_allowed(query)))):
        return False
    graph_capture = bool(getattr(attn_metadata, 'flash_v100_cudagraph_capture', False)) or _routing._is_cuda_graph_capturing(query)
    effective_seq_hint = max(int(max_seq_len_hint or 0), int(workspace_seq_capacity_hint or 0) if graph_capture else 0)
    min_seq_len = int(os.getenv('VLLM_FLASH_V100_SMALLQ_DECODE_XQA_MIN_SEQ_LEN', '4096'))
    if fp8_e5m2_kv:
        min_seq_len = max(min_seq_len, _routing._decode_fp8_xqa_min_seq_len())
    return effective_seq_hint >= max(1, min_seq_len)
